 motor:{id:'motor',name:'Motor',icon:'🛵',price:300,domain:'land',available:true,speed:35,description:'Pilihan darat yang lebih pantas daripada berjalan kaki dan bas jelajah.',timing:'35 km/j · kira-kira 35 saat permainan / km',assumption:'Andaian permainan 35 km/j di rangkaian jalan kenderaan, tanpa trafik langsung.'},
